                 // строк — их детектор уже нашёл и вырезал по размеру.
                 val rescued = rescueRejectedLines(rejected)
                 if (rescued.isNotEmpty()) {
                     OcrStageBus.post(OcrStageBus.Stage.DONE, "rescue: ${rescued.length} символов")
                     return@withLock rescued
                 }
                 OcrStageBus.post(OcrStageBus.Stage.DONE, "цельностраничный rescue")
                 return@withLock recognizeWholeImageFallback(image)
             }

             // Крупный «заголовочный» текст (широкие жирные кропы) часто не
             // проходит порог уверенности, хотя читается визуально. Если он
             // молча отбрасывается, верх страницы пропадает («в начале вверху
             // пропускает»), пока мелкий водяной знак распознаётся нормально.
             val allLines = recognized + salvageRejectedLines(rejected, recognized)

             val rows = mutableListOf<MutableList<Pair<TextBox, String>>>()
             allLines.forEach { item ->
                 val row = rows.firstOrNull { existing ->
                     val center = existing.map { it.first.centerY }.average().toFloat()
                     val height = existing.map { it.first.height }.average().toFloat()
                     abs(item.first.centerY - center) <= max(item.first.height.toFloat(), height) * 0.60f
                 }
                 if (row != null) row += item else rows += mutableListOf(item)
             }
             rows.sortBy { row -> row.minOf { it.first.rect.top } }
             val text = rows.joinToString("\n") { row ->
                 row.sortedBy { it.first.rect.left }.joinToString(" ") { it.second.trim() }
             }
             val out = cleanRecognition(textPostprocessor.postprocess(text))
             OcrStageBus.post(
                 OcrStageBus.Stage.DONE,
                 "${out.length} симв | словарь: ${OcrTextCleanerStats.wordDictHits}, " +
                     "пунктуация: ${OcrTextCleanerStats.punctFixes}, " +
                     "разбиение: ${OcrTextCleanerStats.splitFixes}",
             )
             out
         }
         } catch (e: Exception) {
             OcrStageBus.post(OcrStageBus.Stage.FAILED, e.javaClass.simpleName)
             throw e
         }
     }

     /**
      * Второй rescue-эшелон: лучшие из строк, отклонённых по уверенности.
      *
      * Устройство сообщало о подписях, которые не дают никакого результата,
      * хотя детектор их видел. Первый эшелон ([recognizeWholeImageFallback])
      * здесь почти не помогает: он уменьшает весь лист до 320x48, и компактная
      * подпись становится нечитаемой. Здесь же берутся уже вырезанные по боксам
      * кропы — тот же материал, который не прошёл порог уверенности.
      *
      * Возвращается результат только если он проходит все текстовые фильтры
      * (кириллица, «словарная лесенка», пословный salvage). Ничего не
      * додумывается: это выбор лучшего из уже распознанного.
      */
     private fun rescueRejectedLines(rejected: List<Pair<TextBox, Recognition>>): String {
         if (rejected.isEmpty()) return ""
         val candidates = rejected
             // Полупрозрачный водяной знак не должен «оживать» в rescue-эшелоне.
             .filter { (_, recognition) -> recognition.inkRatio >= tuning().minCropInkRatio }
             .map { (box, recognition) -> box to recognition.text.trim() }
             .filter { (_, text) -> text.isNotBlank() }
             .sortedByDescending { (_, text) -> text.count(Char::isLetter) }
             .take(tuning().rescueMaxLines)
         if (candidates.isEmpty()) return ""

         val rows = mutableListOf<MutableList<Pair<TextBox, String>>>()
         candidates.forEach { item ->
             val row = rows.firstOrNull { existing ->
                 val center = existing.map { it.first.centerY }.average().toFloat()
                 val height = existing.map { it.first.height }.average().toFloat()
                 abs(item.first.centerY - center) <= max(item.first.height.toFloat(), height) * 0.60f
             }
             if (row != null) row += item else rows += mutableListOf(item)
         }
         rows.sortBy { row -> row.minOf { it.first.rect.top } }
         val text = rows.joinToString("\n") { row ->
             row.sortedBy { it.first.rect.left }.joinToString(" ") { it.second }
         }
         return cleanRecognition(textPostprocessor.postprocess(text))
     }

     /**
      * Лучшие из отклонённых по уверенности строк, которые всё же выглядят
      * как читаемая кириллица, добавляются к принятым строкам страницы.
      *
      * Раньше rejected использовались только когда НИЧЕГО не распозналось
      * ([rescueRejectedLines]). Если page детектор находит и большую надпись
      * вверху, и мелкий водяной знак, знак проходил порог уверенности и
      * верхняя строка молча пропадала из результата. Спасаем только чистую
      * кириллицу без дублей — реальный текст не теряется, мусор не оживает.
      */
     private fun salvageRejectedLines(
         rejected: List<Pair<TextBox, Recognition>>,
         recognized: List<Pair<TextBox, String>>,
     ): List<Pair<TextBox, String>> {
         if (rejected.isEmpty()) return emptyList()
         val acceptedTexts = recognized.mapTo(HashSet()) { it.second }
         return rejected
             .filter { (_, recognition) -> recognition.inkRatio >= tuning().minCropInkRatio }
             .map { (box, recognition) -> box to recognition.text.trim() }
             .filter { (_, text) -> text.isNotBlank() }
             .filter { (_, text) -> text !in acceptedTexts }
             .filter { (_, text) ->
                 val normalized = OcrTextCleaner.normalizeLocalCyrillicCaption(text).trim()
                 normalized.count(Char::isLetter) >= 4 &&
                     !OcrTextCleaner.looksLikeDictionaryRamp(normalized) &&
                     OcrTextCleaner.isAcceptableCyrillicOcrText(normalized)
             }
             .distinctBy { it.second }
             // Крупный заголовочный текст (широкие боксы) часто получает низкую
             // уверенность и уходит в rejected. Сортируем по «объёму буквы» —
             // число букв × площадь бокса — чтобы крупные надписи не затерялись
             // среди мелкого шума.
             .sortedByDescending { (box, text) ->
                 text.count(Char::isLetter) * box.rect.width().toLong() * box.rect.height().toLong()
             }
             .take(tuning().rescueMaxLines)
     }

     /**
      * Последний локальный rescue-проход для больших облачков и декоративных
      * шрифтов, которые детектор видит, но построчный путь не принимает. Он
      * возвращает только валидный кириллический результат; это не словарная
      * генерация и не облачный fallback.
      */
     private fun recognizeWholeImageFallback(image: Bitmap): String {
         val result = recognizeCrop(image)
         if (result.text.isBlank() || !acceptsConfidence(result)) return ""
         return cleanRecognition(textPostprocessor.postprocess(result.text))
     }

     /**
      * Нужно ли разрезать кроп по столбцам: только когда при нормальном
      * масштабе (высота 48px) распознаваемая ширина превышает фиксированный
      * вход 320x48, иначе кроп ужимается и широкий заголовок не читается.
      */
     private fun needsWideChunking(crop: Bitmap): Boolean =
         crop.width * RECOGNIZER_HEIGHT > crop.height * RECOGNIZER_WIDTH

     /**
      * Распознавание слишком широкого кропа по горизонтальным кускам.
      *
      * Распознаватель принимает фиксированный вход [RECOGNIZER_WIDTH]x
      * [RECOGNIZER_HEIGHT]; кроп пропорционально шире (заголовок во всю
      * страницу) ужимался до 320px и превращался в мусор с низкой
      * уверенностью — такие строки молча пропадали из результата. Здесь кроп
      * режется на куски, каждый из которых при масштабе 48px по высоте
      * укладывается во входную ширину, с небольшим перекрытием чтобы буквы,
      * попавшие на стык, не терялись.
      */
     private fun recognizeWideChunks(crop: Bitmap): Recognition {
         val chunkSourceW = ((RECOGNIZER_WIDTH - 8) * crop.height / RECOGNIZER_HEIGHT).coerceAtLeast(16)
         val overlap = (chunkSourceW * 0.12f).toInt().coerceAtLeast(8)
         val pieces = mutableListOf<Recognition>()
         var x = 0
         while (x < crop.width) {
             val right = min(crop.width, x + chunkSourceW)
             val chunk = Bitmap.createBitmap(crop, x, 0, right - x, crop.height)
             val piece = try {
                 recognizeCrop(chunk)
             } finally {
                 chunk.recycle()
             }
             if (piece.text.isNotBlank()) pieces += piece
             if (right >= crop.width) break
             x = right - overlap + 1
             if (x >= right) x = right
         }
         if (pieces.isEmpty()) return Recognition("", 0f, coverage = 0f)
         return Recognition(
             text = pieces.joinToString(" ") { it.text.trim() }.trim(),
             confidence = pieces.fold(0f) { acc, p -> acc + p.confidence } / pieces.size,
             model = pieces.maxByOrNull { it.confidence }?.model ?: RecognitionModel.V3,
             coverage = pieces.fold(0f) { acc, p -> acc + p.coverage } / pieces.size,
             inkRatio = pieces.fold(0f) { acc, p -> acc + p.inkRatio } / pieces.size,
         )
     }

     /**
      * Распознавание ОДНОЙ вырезанной строки (кроп по боксу детектора).
      *
      * В отличие от [recognizeText] не запускает детектор повторно: строка уже
      * вырезана, а второй проход detectTextBoxes() по кропу дробил надпись на
      * фрагменты букв, и распознаватель выдавал мусор вместо реплики.
      */
     override suspend fun recognizeLine(image: Bitmap): String {
         ensureInitialized()
         return mutex.withLock {
             require(!image.isRecycled) { "Input bitmap is recycled" }
             if (image.width < 4 || image.height < 4) return@withLock ""
             val kind = OcrBoxGeometry.classifyKind(
                 left = 0,
                 top = 0,
                 right = image.width,
                 bottom = image.height,
                 imageWidth = image.width,
                 imageHeight = image.height,
             )
             val crop = if (kind == OcrBoxGeometry.Kind.VERTICAL) rotate90cw(image) else image
             try {
                 // Бокс детектора — это строка, но для колонок манхвы он вмещает
                 // несколько строк сразу. Режем их горизонтально и читаем по
                 // очереди: одна колонка больше не проходит через распознаватель
                 // как один 320×48-слепок.
                 val text = recognizeMultiLine(crop) ?: run {
                     val result = recognizeLineBitmap(crop)
                     if (result.text.isBlank() || !acceptsConfidence(result)) "" else result.text
                 }
                 if (text.isBlank()) return@withLock ""
                 cleanRecognition(textPostprocessor.postprocess(text))
             } finally {
                 if (crop !== image && !crop.isRecycled) crop.recycle()
             }
         }
     }

     /**
      * Распознаёт кроп как несколько строк, если проекция строк это показывает.
      * null — когда кроп уже одна строка и резать нечего.
      */
     private fun recognizeMultiLine(crop: Bitmap): String? {
         val bands = lineBands(crop) ?: return null
         val pieces = mutableListOf<String>()
         var confidenceSum = 0f
         var coverageSum = 0f
         var inkSum = 0f

         var count = 0
         for (band in bands) {
             val piece = bandBitmap(crop, band) ?: continue
             val recognition = try {
                 recognizeLineBitmap(piece)
             } finally {
                 if (!piece.isRecycled) piece.recycle()
             }
             if (recognition.text.isNotBlank()) {
                 pieces += recognition.text
                 confidenceSum += recognition.confidence
                 coverageSum += recognition.coverage
                 inkSum += recognition.inkRatio

                 count++
             }
         }
         if (pieces.isEmpty()) return null
         // Собираем признак составного результата из реальных метрик полос: без
         // среднего `inkRatio` `acceptsConfidence` всегда отклоняла его (0f <
         // minCropInkRatio), и весь многострочный разбор молча не работал.
         val text = pieces.joinToString(" ")
         val accepted = acceptsConfidence(
             Recognition(
                 text = text,
                 confidence = if (count == 0) 0f else confidenceSum / count,
                 coverage = if (count == 0) 0f else coverageSum / count,
                 inkRatio = if (count == 0) 0f else inkSum / count,
             ),
         )
         if (!accepted) return null
         return text

     }

     /**
      * Полосы текста внутри кропа или null, если кроп — одна строка.
      *
      * Один детекторный бокс = одна строка почти всегда, поэтому критерии
      * намеренно строгие: три и более строки сопоставимой высоты. Всё, что
      * слабее, читается как раньше — целиком.
      */
     private fun lineBands(crop: Bitmap): List<IntRange>? {
         if (crop.height < tuning().lineSplitMinHeightPx) return null
         val w = crop.width
         val h = crop.height
         val pixels = IntArray(w * h)
         crop.getPixels(pixels, 0, w, 0, 0, w, h)
         val gray = IntArray(w * h)
         val hist = IntArray(256)
         for (i in pixels.indices) {
             val p = pixels[i]
             val lum = (77 * ((p shr 16) and 0xFF) + 150 * ((p shr 8) and 0xFF) + 29 * (p and 0xFF)) shr 8
             gray[i] = lum
             hist[lum]++
         }
         val otsu = otsuThreshold(gray, hist)
         val rowInk = FloatArray(h)
         for (y in 0 until h) {
             val row = y * w
             var ink = 0
             for (x in 0 until w) {
                 if (gray[row + x] < otsu) ink++
             }
             rowInk[y] = ink.toFloat() / w
         }
         val minInk = tuning().lineSplitMinInkRatio
         val bands = ocrLineBands(
             rowInk = rowInk,
             minInkRatio = minInk,
             maxGapFactor = tuning().lineSplitMaxGapFactor,
             minBandHeight = max(2, round(h * minInk * 0.5f).toInt()),
             // Две строки подряд дёшево прочитать целиком, и риск разрезать
             // глифы не стоит лишнего прохода. Режем колонки от трёх строк.
             minBands = 3,
         ).filter { it.count() * 3 >= h / 2 }
         if (bands.isEmpty()) return null
         // Покрытие: читать ТОЛЬКО полосы можно лишь если они накрывают все
         // строки с чернилами. Иначе короткий блок (два слова, мало чернил)
         // остался бы вне полос и его текст пропал бы молча — это и было
         // «потерялось слово» на кропе из трёх мелких или двух крупных блоков.
         // Лучше прочитать кроп целиком: он сожмётся, но не потеряет текст.
         val covered = BooleanArray(h)
         bands.forEach { band ->
             for (y in band) covered[y] = true
         }
         for (y in 0 until h) {
             if (rowInk[y] > 0f && !covered[y]) return null
         }
         return bands
     }

     /** Вырезает полосу строки с вертикальным запасом, чтобы не срезать край глифа. */
     private fun bandBitmap(crop: Bitmap, band: IntRange): Bitmap? {
         val top = max(0, band.first - tuning().lineSplitPadPx)
         val bottom = min(crop.height, band.last + 1 + tuning().lineSplitPadPx)
         if (bottom - top < 4) return null
         return runCatching { Bitmap.createBitmap(crop, 0, top, crop.width, bottom - top) }
             .onFailure { logcat(LogPriority.WARN) { "Line band crop failed: ${it.message}" } }
             .getOrNull()
     }

     /**
      * Распознаёт вырезанную детектором строку.
      *
      * Детектор PP-OCR склеивает короткую строку в один бокс, а распознаватель
      * обучен на отдельных словах и на целой строке не выдаёт пробелов:
      * «И ПАЛ ПОД ЛЕЗВИЕМ» выходило как «ИПАЛПОДЛЕЗВИЕМ». Раньше строка всегда
      * читалась ДВАЖДЫ: целиком и по словам, а результат выбирался по оценке.
      * Это удваивало-утраивало инференс каждой реплики ради сравнения, которое
      * чаще всего выигрывала целая строка.
      *
      * Теперь нарезка на слова запускается только там, где она действительно
      * нужна: если консервативная постобработка уже восстановила границы слов в
      * целой строке, результат нечитаемым не будет и второй проход не нужен.
      * На строке без пробелов (главный случай поломанного текста) нарезка
      * остаётся, иначе TTS получил бы «ИПАЛПОДЛЕЗВИЕМ».
      */
     private fun recognizeLineBitmap(crop: Bitmap): Recognition {
         // PP-OCRv5 надёжно читает многие компактные строковые подписи целиком,
         // но в CTC-выходе не ставит пробелы. Не заменяем целую строку только
         // нарезанными словами: на тонких буквах нарезка может обрезать край
         // глифа и вернуть пустой результат, хотя полный кроп читается верно.
         val wholeLine = recognizeCrop(crop)
         if (!needsWordSegmentation(wholeLine)) return wholeLine
         val words = splitWords(crop)
         if (words.size == 1) {
             // Слишком широкий кроп (заголовок/надпись во всю страницу)
             // распознаватель ужимает до 320px, и текст становится нечитаемым,
             // а строка уходит в rejected. Режем кроп по столбцам с небольшим
             // перекрытием и распознаём куски по отдельности.
             if (needsWideChunking(crop)) {
                 val chunked = recognizeWideChunks(crop)
                 if (chunked.text.isNotBlank() && candidateQuality(chunked) >= candidateQuality(wholeLine)) {
                     return chunked
                 }
             }
             return wholeLine
         }
         val pieces = mutableListOf<String>()
         var confSum = 0f
         var inkSum = 0f
         var recognizedCount = 0
         for (piece in words) {
             try {
                 val r = recognizeCrop(piece)
                 if (r.text.isNotBlank()) {
                     confSum += r.confidence
                     inkSum += r.inkRatio
                     recognizedCount++
                     pieces += r.text.trim()
                 }
             } finally {
                 piece.recycle()
             }
         }
         // Нарезка режет СЛОВА, а не буквы. На коротком кропе (одно-три слова)
         // вертикальная проекция находит щели внутри слов — «что-то» делилось
         // на «ч»/«то»/«т», и результат склеивался с пробелами. Читатель
         // получал «ч то т» вместо «что-то», при этом длинная строка читалась
         // идеально: в ней CTC уже ставит пробелы и нарезка не запускается.
         if (segmentationIsDestructive(wholeLine.text, pieces)) return wholeLine
         val segmented = Recognition(
             text = pieces.joinToString(" ").trim(),
             confidence = if (recognizedCount == 0) 0f else confSum / recognizedCount,
             model = wholeLine.model,
             coverage = wholeLine.coverage,
             inkRatio = if (recognizedCount == 0) 0f else inkSum / recognizedCount,
         )
         return selectLineRecognition(wholeLine, segmented)
     }

     /**
      * Стоит ли тратить инференс на нарезку строки на слова.
      *
      * Если в целой строке уже есть границы слов (или она слишком короткая,
      * чтобы что-то резать) — читаемый результат получен, второй проход
      * ничего не добавит. Режем только строки, где слов нет вообще: это
      * ровно тот случай, где TTS получает слитную кашу.
      */
     private fun needsWordSegmentation(wholeLine: Recognition): Boolean {
         if (wholeLine.text.isBlank()) return true
         if (wholeLine.text.count(Char::isWhitespace) > 0) return false
         val restored = OcrTextCleaner.normalizeLocalCyrillicCaption(wholeLine.text)
         return restored.count(Char::isWhitespace) == 0
     }

     /**
      * Выбирает между полной строкой и визуально разрезанными словами.
      * Полный вариант допускается только если консервативная постобработка уже
      * способна восстановить в нём реальные границы слов. Это не словарная
      * подмена: неизвестные слитные последовательности не получают бонуса и
      * остаются на пути с визуальными промежутками.
      */
     private fun selectLineRecognition(wholeLine: Recognition, segmented: Recognition): Recognition {
         if (segmented.text.isBlank()) return wholeLine
         if (wholeLine.text.isBlank()) return segmented

         val restoredWhole = OcrTextCleaner.normalizeLocalCyrillicCaption(wholeLine.text)
         val restoresBoundaries = restoredWhole.count(Char::isWhitespace) > wholeLine.text.count(Char::isWhitespace)
         val wholeQuality = candidateQuality(wholeLine) + if (restoresBoundaries) tuning().wholeLineBoundaryBonus else 0f
         val segmentedQuality = candidateQuality(segmented)
         return if (restoresBoundaries && wholeQuality >= segmentedQuality) wholeLine else segmented
     }

     /**
      * Порог Оцу по гистограмме яркости: максимизирует межклассовую дисперсию.
      * Один и тот же порог нужен и нарезке на слова, и разбору кропа на строки.
      */
     private fun otsuThreshold(gray: IntArray, hist: IntArray): Int {
         var sumAll = 0L
         for (v in 0..255) sumAll += v * hist[v]
         val total = gray.size.toLong()
         var sumB = 0L
         var wB = 0L
         var maxBetween = -1.0
         var otsu = 127
         for (v in 0..255) {
             wB += hist[v]
             if (wB == 0L) continue
             val wF = total - wB
             if (wF == 0L) break
             sumB += v * hist[v]
             val mB = sumB.toDouble() / wB
             val mF = (sumAll - sumB).toDouble() / wF
             val between = wB.toDouble() * wF * (mB - mF) * (mB - mF)
             if (between > maxBetween) {
                 maxBetween = between
                 otsu = v
             }
         }
         return otsu
     }

     /**
      * Вертикальная проекция чернил + порог Оцу: широкие пробелы между словами
      * разделяют кроп. Если явной щели нет — кроп остаётся целым.
      */
     private fun splitWords(crop: Bitmap): List<Bitmap> {
         if (crop.width < tuning().splitMinWidthPx) return listOf(crop)
         val w = crop.width
         val h = crop.height
         val pixels = IntArray(w * h)
         crop.getPixels(pixels, 0, w, 0, 0, w, h)
         val gray = IntArray(w * h)
         val hist = IntArray(256)
         for (i in pixels.indices) {
             val p = pixels[i]
             val lum = (77 * ((p shr 16) and 0xFF) + 150 * ((p shr 8) and 0xFF) + 29 * (p and 0xFF)) shr 8
             gray[i] = lum
             hist[lum]++
         }
         // Порог Оцу по гистограмме яркости.
         val otsu = otsuThreshold(gray, hist)
         fun inkColumns(lightInk: Boolean): IntArray {
             // Balloon borders are often long solid black/white rows. Counting
             // their pixels as ink marks every column as occupied and prevents
             // spaces from being split. Exclude only near-full rows; glyph rows
             // retain their normal sparse stroke pattern.
             val usableRows = BooleanArray(h)
             var usableRowCount = 0
             for (y in 0 until h) {
                 var active = 0
                 for (x in 0 until w) {
                     val g = gray[y * w + x]
                     if (if (lightInk) g > otsu else g < otsu) active++
                 }
                 if (active in 1 until (w * 0.72f).toInt().coerceAtLeast(1)) {
                     usableRows[y] = true
                     usableRowCount++
                 }
             }
             // A crop can be a very bold word whose strokes occupy most rows.
             // In that case retain the central band instead of discarding all
             // signal, while still ignoring possible frame edges.
             val useCentralBand = usableRowCount < max(2, h / 6)
             val margin = max(1, h / 10)
             val col = IntArray(w)
             for (x in 0 until w) {
                 var c = 0
                 for (y in 0 until h) {
                     if (useCentralBand && (y < margin || y >= h - margin)) continue
                     if (!useCentralBand && !usableRows[y]) continue
                     val g = gray[y * w + x]
                     if (if (lightInk) g > otsu else g < otsu) c++
                 }
                 col[x] = c
             }
             return col
         }
         // Тёмные чернила на светлом фоне; если фон тёмный (светлый текст) —
         // большинство колонок «активны», тогда инвертируем.
         var ink = inkColumns(false)
         if (ink.count { it > 0 } > w * 7 / 10) ink = inkColumns(true)
         val runs = mutableListOf<IntArray>()
         var start = -1
         for (x in 0 until w) {
             if (ink[x] > 0) {
                 if (start < 0) start = x
             } else if (start >= 0) {
                 runs.add(intArrayOf(start, x - 1))
                 start = -1
             }
         }
         if (start >= 0) runs.add(intArrayOf(start, w - 1))
         if (runs.size < 2) return listOf(crop)
         val gaps = IntArray(runs.size - 1) { i -> runs[i + 1][0] - runs[i][1] - 1 }
         val threshold = ocrWordGapThreshold(
             gaps = gaps,
             wordGapFactor = tuning().wordGapFactor,
             minWordGapPx = tuning().minWordGapPx,
         )
         var splitAfter = 0
         val groups = mutableListOf<IntArray>()
         var groupStart = runs[0][0]
         for (i in gaps.indices) {
             if (gaps[i] >= threshold) {
                 groups.add(intArrayOf(groupStart, runs[i][1]))
                 groupStart = runs[i + 1][0]
                 splitAfter++
             }
         }
         if (splitAfter == 0) return listOf(crop)
         groups.add(intArrayOf(groupStart, runs[runs.size - 1][1]))
         if (groups.size <= 1) return listOf(crop)
         return groups.map { g ->
             val left = max(0, g[0] - 4)
             val right = min(w, g[1] + 5)
             Bitmap.createBitmap(crop, left, 0, max(1, right - left), h)
         }
     }

     /**
      * Пословная правка омоглифов и фильтр мусора «словарной лесенкой».
      * Пословная — чтобы чистая латынь («SOS», «Wi-Fi») оставалась латынью и
      * TTS не читал её по буквам внутри русских слов.
      */
     private fun acceptsConfidence(result: Recognition): Boolean {
         val letters = result.text.count(Char::isLetter)
         val threshold = if (letters in 1..3) {
             tuning().shortTextMinConfidence
         } else {
             tuning().minAcceptConfidence
         }
         // Полупрозрачный мелкий водяной знак почти не оставляет «чернил»:
         // даже с высокой уверенностью распознавателя его нельзя читать вслух.
         if (result.inkRatio < tuning().minCropInkRatio) return false
         // Пропущенные в середине слова шаги (blank) понижают уверенность:
         // «лжн вбинен» вместо «ЛОЖНО ОБВИНЁН» больше не проходит как хороший
         // результат только потому, что уцелевшие буквы были прочитаны чётко.
         val discounted = CtcScoring.coveragePenalty(result.confidence, result.coverage, tuning().minCoverage)
         return discounted >= threshold
     }

     private fun cleanRecognition(text: String): String {
         // Склеиваем переносы с дефисом ДО того, как postprocessing превратит
         // строковые границы в пробелы. Иначе «НЕУПРАВ-\nЛЯЕМЫЙ» остаётся в
         // интерфейсе как ложное «НЕУПРАВ- ЛЯЕМЫЙ».
         val cleaned = OcrTextCleaner.normalizeLocalCyrillicCaption(text).trim()
         if (cleaned.isEmpty() || OcrTextCleaner.looksLikeDictionaryRamp(cleaned)) return ""
         if (OcrTextCleaner.isAcceptableCyrillicOcrText(cleaned)) return cleaned
         // Один мусорный токен не обнуляет всю подпись: чистая кириллица
         // сохраняется, оставшаяся латынь проходит только из белого списка —
         // «v i m» вместо «ШУМ» читать вслух нельзя.
         return OcrTextCleaner.acceptableAfterSalvage(cleaned)
     }

     private fun detectTextBoxes(image: Bitmap): List<TextBox> {
         val boxes = runDetection(image, 0, 0).toMutableList()
         // Тайловая развёртка: на страницах высокого разрешения мелкие
         // облачка исчезают, когда весь лист ужат в квадрат детектора, —
         // прогоняем модель дополнительно по плиткам 2×2 с перекрытием 12%.
         // Но четыре лишних прохода на КАЖДЫЙ кадр — главный тормоз локального
         // OCR в авточтении. Если основной проход уже нашёл достаточно боксов,
         // тайлы почти наверняка не добавят нового текста — пропускаем их.
         if (max(image.width, image.height) > DETECTOR_SIZE && boxes.size < tuning().tilingMinTextBoxes) {
             val overX = (image.width * 0.12f).toInt()
             val overY = (image.height * 0.12f).toInt()
             val halfW = image.width / 2
             val halfH = image.height / 2
             val tiles = listOf(
                 intArrayOf(0, 0, halfW + overX, halfH + overY),
                 intArrayOf(halfW - overX, 0, image.width, halfH + overY),
                 intArrayOf(0, halfH - overY, halfW + overX, image.height),
                 intArrayOf(halfW - overX, halfH - overY, image.width, image.height),
             )
             for (t in tiles) {
                 val l = t[0].coerceAtLeast(0)
                 val tp = t[1].coerceAtLeast(0)
                 val r = t[2].coerceAtMost(image.width)
                 val bt = t[3].coerceAtMost(image.height)
                 if (r - l < 96 || bt - tp < 96) continue
                 val crop = Bitmap.createBitmap(image, l, tp, r - l, bt - tp)
                 try {
                     boxes += runDetection(crop, l, tp)
                 } finally {
                     crop.recycle()
                 }
             }
         }
         val merged = mergeBoxes(boxes, tuning())
         // Облачков нет, но текст есть: рамки строятся проекцией чернил —
         // текст не должен теряться из-за того, что детектор не нашёл пузырь.
         if (merged.isEmpty()) return projectionBoxes(image)
         return merged.take(tuning().maxTextBoxes).map(::TextBox)
     }

     /** Один проход детектора по области; координаты — в системе исходника. */
     private fun runDetection(source: Bitmap, offX: Int, offY: Int): List<Rect> {

         detectorCanvas.drawColor(Color.WHITE)
         val scale = min(DETECTOR_SIZE.toFloat() / source.width, DETECTOR_SIZE.toFloat() / source.height)
         val scaledWidth = max(1, (source.width * scale).toInt())
         val scaledHeight = max(1, (source.height * scale).toInt())
         val offsetX = (DETECTOR_SIZE - scaledWidth) / 2
         val offsetY = (DETECTOR_SIZE - scaledHeight) / 2
         detectorCanvas.drawBitmap(
             source,
             null,
             Rect(offsetX, offsetY, offsetX + scaledWidth, offsetY + scaledHeight),
             detectorPaint,
         )
         detectorBitmap.getPixels(detectorPixels, 0, DETECTOR_SIZE, 0, 0, DETECTOR_SIZE, DETECTOR_SIZE)

         var out = 0
         detectorPixels.forEach { pixel ->
             val r = (pixel shr 16) and 0xFF
             val g = (pixel shr 8) and 0xFF
             val b = pixel and 0xFF
             // Модели PaddleOCR обучены в BGR (OpenCV): синий канал идёт первым,
             // константы нормализации — по позициям каналов, как в rapidocr.
             detectorFloats[out++] = (b / 255f - 0.485f) / 0.229f
             detectorFloats[out++] = (g / 255f - 0.456f) / 0.224f
             detectorFloats[out++] = (r / 255f - 0.406f) / 0.225f
         }
         detectorInput.writeFloat(detectorFloats)
         detector.run(listOf(detectorInput), listOf(detectorOutput))
         val probability = detectorOutput.readFloat()
         if (probability.size < DETECTOR_SIZE * DETECTOR_SIZE) return emptyList()

         visited.fill(false)
         val boxes = mutableListOf<Rect>()
         val limit = DETECTOR_SIZE * DETECTOR_SIZE
         for (start in 0 until limit) {
             if (visited[start] || probability[start] < tuning().detectorThreshold) continue
             var head = 0
             var tail = 0
             componentQueue[tail++] = start
             visited[start] = true
             var minX = DETECTOR_SIZE
             var minY = DETECTOR_SIZE
             var maxX = 0
             var maxY = 0
             var area = 0
             while (head < tail) {
                 val index = componentQueue[head++]
                 val x = index % DETECTOR_SIZE
                 val y = index / DETECTOR_SIZE
                 minX = min(minX, x)
                 minY = min(minY, y)
                 maxX = max(maxX, x)
                 maxY = max(maxY, y)
                 area++
                 for (dy in -1..1) for (dx in -1..1) {
                     if (dx == 0 && dy == 0) continue
                     val nx = x + dx
                     val ny = y + dy
                     if (nx !in 0 until DETECTOR_SIZE || ny !in 0 until DETECTOR_SIZE) continue
                     val next = ny * DETECTOR_SIZE + nx
                     if (!visited[next] && probability[next] >= tuning().detectorThreshold) {
                         visited[next] = true
                         componentQueue[tail++] = next
                     }
                 }
             }
             if (area < tuning().minComponentArea || maxX - minX < 3 || maxY - minY < 3) continue
             val expandX = max(3, ((maxX - minX) * 0.16f).toInt())
             val expandY = max(2, ((maxY - minY) * 0.20f).toInt())
-            val left = offX + (((minX - expandX - offsetX) / scale).toInt()).coerceIn(0, source.width - 1)
-            val top = offY + (((minY - expandY - offsetY) / scale).toInt()).coerceIn(0, source.height - 1)
-            val right = (offX + ceil((maxX + expandX - offsetX) / scale).toInt()).coerceIn(left + 1, source.width)
-            val bottom = (offY + ceil((maxY + expandY - offsetY) / scale).toInt()).coerceIn(top + 1, source.height)
+            val left = offX + (((minX - expandX - offsetX) / scale).toInt()).coerceIn(0, max(0, source.width - 1))
+            val top = offY + (((minY - expandY - offsetY) / scale).toInt()).coerceIn(0, max(0, source.height - 1))
+            val right = (offX + ceil((maxX + expandX - offsetX) / scale).toInt())
+                .coerceIn(minOf(left + 1, source.width), source.width)
+            val bottom = (offY + ceil((maxY + expandY - offsetY) / scale).toInt())
+                .coerceIn(minOf(top + 1, source.height), source.height)
             if (right - left >= 6 && bottom - top >= 6) boxes += Rect(left, top, right, bottom)
         }
         return boxes
     }

     /**
      * Рамки текста без модели: Отсу-порог по яркости, проекция чернил по
      * строкам и столбцам. Спасает страницы, где детектор облачков молчит,
      * а текст есть (пользовательское «нет облачков — выдели рамкой и читай»).
      */
     private fun projectionBoxes(image: Bitmap): List<TextBox> {
         val w = 360
         val h = max(8, (image.height * w.toFloat() / image.width).toInt())
         val small = Bitmap.createScaledBitmap(image, w, h, true)
         val px = IntArray(w * h)
         small.getPixels(px, 0, w, 0, 0, w, h)
         small.recycle()
         val gray = IntArray(w * h) { i ->
             val p = px[i]
             (((p shr 16) and 0xFF) * 77 + ((p shr 8) and 0xFF) * 150 + (p and 0xFF) * 29) shr 8
         }
         // Порог Отсу по гистограмме яркости.
         val hist = IntArray(256)
         gray.forEach { hist[it]++ }
         var total = 0L
         for (i in 0..255) total += i * hist[i]
         var sumB = 0L
         var wB = 0
         var best = -1.0
         var thr = 128
         for (t in 0..255) {
             wB += hist[t]
             if (wB == 0) continue
             val wF = w * h - wB
             if (wF == 0) break
             sumB += t * hist[t]
             val mB = sumB.toDouble() / wB
             val mF = (total - sumB).toDouble() / wF
             val between = wB.toDouble() * wF * (mB - mF) * (mB - mF)
             if (between > best) {
                 best = between
                 thr = t
             }
         }
         val sx = image.width.toFloat() / w
         val sy = image.height.toFloat() / h
         val rowInk = FloatArray(h) { y ->
             var ink = 0
             for (x in 0 until w) if (gray[y * w + x] < thr) ink++
             ink.toFloat() / w
         }
         val boxes = mutableListOf<Rect>()
         var y = 0
         while (y < h && boxes.size < 12) {
             if (rowInk[y] < 0.04f) {
                 y++
                 continue
             }
             var y2 = y
             while (y2 < h && rowInk[y2] >= 0.02f) y2++
             if (y2 - y >= max(4, (h * 0.012f).toInt())) {
                 val colInk = FloatArray(w) { x ->
                     var ink = 0
                     for (yy in y until y2) if (gray[yy * w + x] < thr) ink++
                     ink.toFloat() / (y2 - y)
                 }
                 var x = 0
                 while (x < w && boxes.size < 12) {
                     if (colInk[x] < 0.05f) {
                         x++
                         continue
                     }
                     var x2 = x
                     while (x2 < w && colInk[x2] >= 0.02f) x2++
                     if (x2 - x >= 6) {
-                        val left = ((x - 2) * sx).toInt().coerceIn(0, image.width - 2)
-                        val top = ((y - 2) * sy).toInt().coerceIn(0, image.height - 2)
-                        val right = ((x2 + 2) * sx).toInt().coerceIn(left + 8, image.width)
-                        val bottom = ((y2 + 2) * sy).toInt().coerceIn(top + 8, image.height)
+                        val left = ((x - 2) * sx).toInt().coerceIn(0, max(0, image.width - 2))
+                        val top = ((y - 2) * sy).toInt().coerceIn(0, max(0, image.height - 2))
+                        // Нижняя граница не должна переезжать за правый/нижний край:
+                        // иначе coerceIn получает пустой диапазон и падает
+                        // («maximum 447 is less than minimum …») на рамках у края.
+                        val right = ((x2 + 2) * sx).toInt()
+                            .coerceIn(minOf(left + 8, image.width), image.width)
+                        val bottom = ((y2 + 2) * sy).toInt()
+                            .coerceIn(minOf(top + 8, image.height), image.height)
                         boxes += Rect(left, top, right, bottom)
                     }
                     x = x2 + 1
                 }
             }
             y = y2 + 1
         }
         return mergeBoxes(boxes, tuning()).take(tuning().maxTextBoxes).map(::TextBox)
     }

     /** Поворот по часовой: вертикальные облачка читаются как горизонтальные. */
     private fun rotate90cw(src: Bitmap): Bitmap {
         val m = android.graphics.Matrix().apply { postRotate(90f) }
         return Bitmap.createBitmap(src, 0, 0, src.width, src.height, m, true)
     }

     private fun mergeBoxes(source: List<Rect>, tuning: OcrTuning): List<Rect> {
         val boxes = source.sortedWith(compareBy({ it.top }, { it.left })).map(::Rect).toMutableList()
         var changed = true
         while (changed) {
             changed = false
             outer@ for (i in boxes.indices) {
                 for (j in i + 1 until boxes.size) {
                     val a = boxes[i]
                     val b = boxes[j]
                     val overlapY = max(0, min(a.bottom, b.bottom) - max(a.top, b.top))
                     val minHeight = min(a.height(), b.height()).coerceAtLeast(1)
                     val gapX = max(0, max(a.left, b.left) - min(a.right, b.right))
                     if (
                         overlapY >= minHeight * tuning.mergeOverlapYFactor &&
                         gapX <= max(a.height(), b.height()) * tuning.mergeGapXFactor
                     ) {
                         a.union(b)
                         boxes.removeAt(j)
                         changed = true
                         break@outer
                     }
                 }
             }
         }
         return boxes.sortedWith(compareBy({ it.top }, { it.left }))
     }

     private fun pad(rect: Rect, width: Int, height: Int): Rect {
         val px = max(2, (rect.width() * 0.04f).toInt())
         val py = max(2, (rect.height() * 0.12f).toInt())
         return Rect(
             (rect.left - px).coerceAtLeast(0),
             (rect.top - py).coerceAtLeast(0),
             (rect.right + px).coerceAtMost(width),
             (rect.bottom + py).coerceAtMost(height),
         )
     }

     private fun recognizeCrop(crop: Bitmap): Recognition {
         val inkRatio = computeCropInkRatio(crop)
         // Контрастный retry усиливает полупрозрачные водяные знаки так же
         // уверенно, как печатный текст; для кропа почти без чернил он лишь
         // делает водяной знак «надёжным» и тот начинает читаться вслух.
         val allowContrastRetry = tuning().contrastRetryEnabled &&
             inkRatio >= tuning().contrastSkipInkThreshold
         val candidates = mutableListOf(
             runRecognizer(crop, primary, primaryInput, primaryOutput, primaryChars, RecognitionModel.V3),
         )
         if (allowContrastRetry && candidates.last().confidence < tuning().contrastRetryConfidence) {
             val contrast = createHighContrast(crop)
             try {
                 val alternate = runRecognizer(
                     contrast,
                     primary,
                     primaryInput,
                     primaryOutput,
                     primaryChars,
                     RecognitionModel.V3,
                 )
                 candidates += alternate
             } finally {
                 contrast.recycle()
             }
         }
         val secondModel = verifier
         val secondInput = verifierInput
         val secondOutput = verifierOutput
         val secondChars = verifierChars
         if (
             secondModel != null &&
             secondInput != null && secondOutput != null && secondChars != null &&
             tuning().verifierEnabled &&
             !maySkipVerifier(candidates.maxByOrNull(::candidateQuality) ?: candidates.last())
         ) {
             // Device regression showed that v3 may assign a high confidence to
             // Latin-shaped garbage in clean Cyrillic captions. Compare v5 then
             // (rather than treating it as a low-confidence-only fallback) —
             // unless v3 is already confident with clean Cyrillic: then a second
             // full-model pass would only double the latency for no new signal.
             val verifierResult = runRecognizer(
                 crop,
                 secondModel,
                 secondInput,
                 secondOutput,
                 secondChars,
                 RecognitionModel.V5,
             )
             candidates += verifierResult
             if (allowContrastRetry && verifierResult.confidence < tuning().contrastRetryConfidence) {
                 val contrast = createHighContrast(crop)
                 try {
                     candidates += runRecognizer(
                         contrast,
                         secondModel,
                         secondInput,
                         secondOutput,
                         secondChars,
                         RecognitionModel.V5,
                     )
                 } finally {
                     contrast.recycle()
                 }
             }
         }
         return candidates.maxByOrNull(::candidateQuality)
             ?.let { it.copy(inkRatio = inkRatio) }
             ?: Recognition("", 0f, inkRatio = inkRatio)
     }

     /**
      * Можно ли не запускать верификатор PP-OCRv5.
      *
      * v5 удваивает инференс каждого кропа (а кропов — целая строка плюс
      * каждое слово). Пропускаем его только когда v3 уже дал уверенный результат
      * И его текст — чистая кириллица с поправкой омоглифов: именно такие кейсы
      * v5 не исправляет, а «уверенный латино-похожий мусор» из device-регрессии
      * через этот фильтр не проходит и всё равно уходит на сравнение с v5.
      */
     private fun maySkipVerifier(v3: Recognition): Boolean {
         if (v3.text.isBlank()) return false
         if (v3.confidence < tuning().verifierSkipConfidence) return false
         return OcrTextCleaner.isAcceptableCyrillicOcrText(OcrTextCleaner.fixLookalikesPerWord(v3.text))
     }

     /**
      * PP-OCRv3 can report a high softmax score for Latin-shaped noise in comic
      * fonts. When v5 yields valid Cyrillic, prefer it over v3's softmax-only
      * choice. This is model ranking, not spelling replacement; only verified
      * boundary restoration occurs later in [cleanRecognition].
      */
     private fun candidateQuality(candidate: Recognition): Float {
         if (candidate.text.isBlank()) return Float.NEGATIVE_INFINITY
         val fitness = OcrTextCleaner.cyrillicFitness(candidate.text)
         val lengthBonus = min(candidate.text.count(Char::isLetter) * 0.01f, 0.12f)
         val verifierBonus = if (
             candidate.model == RecognitionModel.V5 &&
             OcrTextCleaner.isAcceptableCyrillicOcrText(
                 OcrTextCleaner.fixLookalikesPerWord(candidate.text),
             )
         ) {
             tuning().verifierCyrillicBonus
         } else {
             0f
         }
         // Пользовательский словарь — сильнейший сигнал (читатель сам подтвердил
         // слово), поэтому у него свой бонус; встроенный [RuWordList] даёт бонус
         // поменьше. Оба только РАНЖИРУЮТ гипотезы v3/v5: текст кандидата не
         // меняется, замены слов по словарю по-прежнему запрещены.
         val userDictionaryBonus = tuning().dictionaryCoverageBonus *
             OcrTextCleaner.userDictionaryCoverage(candidate.text)
         val builtinDictionaryBonus = tuning().dictionaryCoverageBonus *
             OcrTextCleaner.dictionaryCoverage(candidate.text)
         return candidate.confidence * fitness + lengthBonus + verifierBonus +
             userDictionaryBonus + builtinDictionaryBonus

     }

     private fun createHighContrast(source: Bitmap): Bitmap {
         val result = Bitmap.createBitmap(source.width, source.height, Bitmap.Config.ARGB_8888)
         val matrix = ColorMatrix().apply {
             setSaturation(0f)
             postConcat(
                 ColorMatrix(
                     floatArrayOf(
                         1.5f, 0f, 0f, 0f, -45f,
                         0f, 1.5f, 0f, 0f, -45f,
                         0f, 0f, 1.5f, 0f, -45f,
                         0f, 0f, 0f, 1f, 0f,
                     ),
                 ),
             )
         }
         Canvas(result).drawBitmap(source, 0f, 0f, Paint(Paint.ANTI_ALIAS_FLAG).apply {
             colorFilter = ColorMatrixColorFilter(matrix)
         })
         return result
     }

     private fun runRecognizer(
         crop: Bitmap,
         model: CompiledModel,
         input: TensorBuffer,
         output: TensorBuffer,
         chars: List<String>,
         recognitionModel: RecognitionModel,
     ): Recognition {
         recognizerCanvas.drawColor(Color.rgb(128, 128, 128))
         val scale = RECOGNIZER_HEIGHT.toFloat() / crop.height.coerceAtLeast(1)
         val targetWidth = (crop.width * scale).toInt().coerceIn(1, RECOGNIZER_WIDTH)
         recognizerCanvas.drawBitmap(
             crop,
             null,
             Rect(0, 0, targetWidth, RECOGNIZER_HEIGHT),
             recognizerPaint,
         )
         recognizerBitmap.getPixels(
             recognizerPixels,
             0,
             RECOGNIZER_WIDTH,
             0,
             0,
             RECOGNIZER_WIDTH,
             RECOGNIZER_HEIGHT,
         )
         var out = 0
         recognizerPixels.forEach { pixel ->
             // BGR, как в эталонной реализации из репозитория моделей:
             // «the original Paddle model was trained with BGR order».
             recognizerFloats[out++] = ((pixel and 0xFF) / 255f - 0.5f) / 0.5f
             recognizerFloats[out++] = (((pixel shr 8) and 0xFF) / 255f - 0.5f) / 0.5f
             recognizerFloats[out++] = (((pixel shr 16) and 0xFF) / 255f - 0.5f) / 0.5f
         }
         input.writeFloat(recognizerFloats)
         model.run(listOf(input), listOf(output))
         val values = output.readFloat()
         // Число классов берём из фактического размера выхода: recognizer'ы
         // пака отдают [1, 40, C] (README репозитория моделей: «для recognizer
         // output — [1, 40, 165]»), то есть C = values.size / 40. Старый код
         // брал C из словаря (163 строки + 1 = 164), окно чтения дрейфовало
         // на один класс за шаг времени, и decode выдавал «лесенку» словаря —
         // «0123456789», «ABCDEFGHIJKLM» — вместо текста. Это и был «баг
         // кодировки» локального OCR.
         val classes = if (values.size % RECOGNIZER_STEPS == 0 && values.size / RECOGNIZER_STEPS >= 2) {
             values.size / RECOGNIZER_STEPS
         } else {
             chars.size + 1
         }
         val decoded = decodeCtc(values, chars, classes)
         return Recognition(
             text = decoded.text,
             confidence = decoded.confidence,
             model = recognitionModel,
             coverage = CtcScoring.innerBlankCoverage(decoded.blankSteps, decoded.emitted, decoded.steps),
         )
     }

     private fun decodeCtc(
         values: FloatArray,
         chars: List<String>,
         classes: Int,
     ): CtcDecode {
         if (classes <= 1 || values.size < classes) return CtcDecode("", 0f, 0, 0, 0)
         val steps = values.size / classes
         val text = StringBuilder(steps)
         var previous = -1
         var confidenceSum = 0f
         var confidenceCount = 0
         // Шаги, на которых победил blank между первым и последним символом.
         var blankSteps = 0
         var countingBlanks = false
         for (step in 0 until steps) {
             val base = step * classes
             val probabilities = CtcScoring.softmax(values, base, classes)
             var bestIndex = 0
             var bestScore = probabilities[0]
             for (index in 1 until classes) {
                 val char = chars.getOrNull(index - 1).orEmpty()
                 if (!allowed(char)) continue
                 val score = probabilities[index]
                 if (score > bestScore) {
                     bestScore = score
                     bestIndex = index
                 }
             }
             when {
                 bestIndex != 0 && bestIndex != previous -> {
                     chars.getOrNull(bestIndex - 1)?.let(text::append)
                     confidenceSum += bestScore
                     confidenceCount++
                     countingBlanks = true
                 }
                 // blank между двумя уже выданными символами = выпавшая буква.
                 bestIndex == 0 && countingBlanks -> blankSteps++
             }
             previous = bestIndex
         }
         return CtcDecode(
             text = text.toString().trim(),
             confidence = if (confidenceCount == 0) 0f else confidenceSum / confidenceCount,
             emitted = confidenceCount,
             blankSteps = blankSteps,
             steps = steps,
         )
     }

     /**
      * Символы, которые модели разрешено выдавать.
      *
      * Латиница раньше была запрещена, и слова вроде «SOS», «BMW», «Wi-Fi»
      * или «3D» терялись целиком: в CTC на шаге запрещённого символа
      * побеждает другой класс или blank, поэтому рвётся всё слово, а не
      * один знак. В русской манге латиница встречается постоянно —
      * звукоподражания, названия, надписи на вывесках.
      */
     private fun allowed(value: String): Boolean {
         if (value.length != 1) return false
         val char = value[0]
         // Русский локальный режим не должен декодировать латинские омоглифы
         // (`i`, `l`, `m`) и цифры как якобы русские буквы. При сомнении лучше
         // получить пустой/слабый результат, чем «разiiiнение» или «мама-нама».
         return char in '\u0400'..'\u052F' ||
             char.isWhitespace() ||
             char in ALLOWED_PUNCTUATION
     }

     override fun close() {
         runBlocking { mutex.withLock { closeInternal() } }
     }

     private fun closeInternal() {
         runCatching { if (::detectorInput.isInitialized) detectorInput.close() }
         runCatching { if (::detectorOutput.isInitialized) detectorOutput.close() }
         runCatching { if (::primaryInput.isInitialized) primaryInput.close() }
         runCatching { if (::primaryOutput.isInitialized) primaryOutput.close() }
         runCatching { verifierInput?.close() }
         runCatching { verifierOutput?.close() }
         verifierInput = null
         verifierOutput = null
         runCatching { if (::detector.isInitialized) detector.close() }
         runCatching { if (::primary.isInitialized) primary.close() }
         runCatching { verifier?.close() }
         verifier = null
         if (::detectorBitmap.isInitialized && !detectorBitmap.isRecycled) detectorBitmap.recycle()
         if (::recognizerBitmap.isInitialized && !recognizerBitmap.isRecycled) recognizerBitmap.recycle()
         initialized = false
     }

     companion object {
         const val PACK = "cyrillic_ocr"
         const val DETECTOR_PATH = "cyrillic_ocr/detector.tflite"
         const val PRIMARY_PATH = "cyrillic_ocr/recognizer_v3.tflite"
         const val VERIFIER_PATH = "cyrillic_ocr/recognizer_v5.tflite"
         const val PRIMARY_DICT_PATH = "cyrillic_ocr/dict_v3.txt"
         const val VERIFIER_DICT_PATH = "cyrillic_ocr/dict_v5.txt"

         private const val DETECTOR_SIZE = 736
         private const val RECOGNIZER_WIDTH = 320
         private const val RECOGNIZER_HEIGHT = 48
         // Число шагов по времени в выходе recognizer'ов пака ([1, 40, C]).
         private const val RECOGNIZER_STEPS = 40
         // Числовые параметры детектора и признания результата перенесены в
         // OcrTuning: ими управляет пресет типа контента (манга / манхва /
         // комикс) и точные переопределения из настроек. Значения по умолчанию
         // в OcrTuning совпадают с прежними константами этого companion object,
         // поэтому BALANCED не меняет поведение приложения.

         private const val ALLOWED_PUNCTUATION = " .,!?;:-()[]{}\"'«»„“”%№+/=…—–"
     }
 }

 internal fun ocrWordGapThreshold(
     gaps: IntArray,
     wordGapFactor: Float,
     minWordGapPx: Int,
 ): Int {
     val positive = gaps.filter { it > 0 }.sorted()
     if (positive.isEmpty()) return minWordGapPx
     if (positive.size <= 2 || positive.first() == positive.last()) return minWordGapPx
     val lowerQuartile = positive[(positive.size - 1) / 4]
     return max(minWordGapPx, round(lowerQuartile * wordGapFactor).toInt())
 }

 /**
  * Похоже ли, что нарезка на слова разрезала текст по БУКВАМ.
  *
  * Нарезка опирается на вертикальную проекцию чернил: щель между словами
  * шире щели между буквами. На коротком кропе (одно-три слова, любой кегль)
  * буквы оказываются шире разрыва между словами, проекция режет текст на
  * фрагменты, а склейка результата с пробелами превращает «что-то» в
  * «ч то т». Длинная строка сюда не попадает: распознаватель уже ставит в ней
  * пробелы, и нарезка не запускается вовсе — поэтому длинный текст читается
  * идеально, а короткий ломается.
  *
  * Два признака разрушающей нарезки:
  * 1. медиана длины куска — одна буква: куски не слова, а огрызки;
  * 2. в кусках потеряно больше [minKeptPercent]% символов целой строки: куски
  *    вырезаны не из этого кропа или срезаны по краям.
  *
  * Одиночная короткая буква рядом с настоящими словами («да нет а») признаком
  * не считается: медиана там длиннее, а символы не теряются.
  *
  * @param wholeLine текст, прочитанный целиком (эталон).
  * @param pieces распознанные куски по порядку слева направо.
  * @param minKeptPercent сколько процентов символов строки обязано уцелеть.
  */
 internal fun segmentationIsDestructive(
     wholeLine: String,
     pieces: List<String>,
     minKeptPercent: Int = 60,
 ): Boolean {
     val lengths = pieces.map { it.trim().length }.filter { it > 0 }.sorted()
     if (lengths.isEmpty()) return false
     if (lengths[lengths.size / 2] <= 1) return true
     val whole = wholeLine.count { !it.isWhitespace() }
     if (whole == 0) return false
     val kept = pieces.sumOf { it.count { ch -> !ch.isWhitespace() } }
     return kept * 100 < whole * minKeptPercent
 }

 /**
  * Разбивает проекцию строк на полосы текста.
  *
  * Детектор PP-OCR склеивает в один бокс не только строку, но и целую колонку
  * манхвы: пять строк подряд приходят одним прямоугольником. Такой кроп
  * распознаватель ужимает до 320×48, пять строк схлопываются в кашу, а
  * последующая нарезка на «слова» режет колонку вертикальными полосами —
  * получаются вертикальные обрывки. Поэтому перед распознаванием кроп
  * режется горизонтально: [rowInk] — доля строк пикселей с чернилами.
  *
  * Параметры подобраны так, чтобы поведение не изменилось у одиночных строк
  * (детектор отдаёт их точно) и у одиночных крупных строк, а ломалось только
  * там, где строк действительно несколько.
  */
 internal fun ocrLineBands(
     rowInk: FloatArray,
     minInkRatio: Float,
     maxGapFactor: Float,
     minBandHeight: Int,
     minBands: Int = 2,
 ): List<IntRange> {
     if (rowInk.size < 2) return emptyList()
     val on = rowInk.mapIndexed { index, ink -> index to ink }.filter { it.second > minInkRatio }
     if (on.isEmpty()) return emptyList()

     val runs = mutableListOf<IntRange>()
     var start = on.first().first
     var previous = on.first().first
     for ((row) in on.drop(1)) {
         if (row > previous + 1) {
             runs += start..previous
             start = row
         }
         previous = row
     }
     runs += start..previous
     if (runs.size < 2) return emptyList()

     // Первая и последняя строка детектора бывают срезанными по краю рамки:
     // их полосы короче реальных. Ориентируемся на медиану — так одна крупная
     // надпись не выдаст себя за «строку» и не испортит разбор колонки.
     val heights = runs.map { it.count() }.sorted()
     val referenceHeight = heights[heights.size / 2]
     if (referenceHeight < minBandHeight) return emptyList()

     // Зазор меньше трети высоты строки — это межстрочный интервал, а не
     // граница строк: полосы разных строк сливаются в одну.
     val maxGap = max(1, round(referenceHeight * maxGapFactor).toInt())
     val merged = mutableListOf<IntRange>()
     for (run in runs) {
         val last = merged.lastOrNull()
         if (last != null && run.first - last.last <= maxGap + 1) {
             merged[merged.lastIndex] = last.first..run.last
         } else {
             merged += run
         }
     }
     // Слишком низкие полосы — это ореолы рамки и остатки букв, а не строки.
     val strong = merged.filter { it.count() >= minBandHeight }
     if (strong.size < minBands) return emptyList()

     // Строки с малым количеством чернил (короткая реплика в два слова) не
     // дотягивают до minInkRatio и выпадали из разбора целиком — блок текста
     // просто исчезал из результата. Расширяем полосы до границ «любых» чернил:
     // первую вверх, последнюю вниз, а промежуток между полосами — только если
     // в нём реально что-то написано (пустые зазоры остаются зазорами).
     val firstInked = rowInk.indexOfFirst { it > 0f }
     val lastInked = rowInk.indexOfLast { it > 0f }
     if (firstInked < 0 || lastInked <= firstInked) return emptyList()
     val bands = strong.mapIndexed { index, band ->
         val from = if (index == 0) firstInked else band.first
         val to = if (index == strong.lastIndex) {
             lastInked
         } else {
             val nextFirst = strong[index + 1].first
             var edge = band.last
             for (y in band.last + 1 until nextFirst) {
                 if (rowInk[y] > 0f) edge = y
             }
             edge
         }
         from..to
     }
     return bands.takeIf { it.size >= minBands } ?: emptyList()
 }

