             val output = resolver.openOutputStream(uri, "w")
             if (output == null) {
                 runCatching { resolver.delete(uri, null, null) }
                 logcat(LogPriority.WARN) { "OcrScreenshotBuffer: openOutputStream returned null for $name" }
