                // Слот говорящего: голос ПРИНАДЛЕЖИТ ПЕРСОНАЖУ, поэтому
                // один и тот же герой звучит одинаково через всю главу, а
                // каждый новый персонаж того же пола получает следующий
                // свободный слот. В режиме «много голосов» и при «свой
                // голос персонажу» включено, иначе голос только по полу.
                val slot = speakerSlotFor(roleMode, gender, region.text, speakerName)

                // Имя уезжает вместе с текстом в движок: словарь ролей
                // читает его из разметки, а метку снимает
                // [SpeechMarkup.strip]. Само слово имени при этом остаётся
                // в тексте реплики, поэтому имя звучит ровно один раз —
                // как на кадре, а не «метка + слово».
                val spokenText = SpeechMarkup.withSpeakerName(
                    SpeechMarkup.strip(speakTextRaw),
                    speakerName,
                )
                // Голос ЯЗЫКА ПЕРЕВОДА (напр. японский дублёр для
                // переведённого на японский текста): hint ставится только
                // если реплика реально читается переведённой, а не в
                // исходнике (фолбэк перевода или stream до подхвата).
                val langHint = if (translate && language != target &&
                    translatedText != null && translatedText != region.text
                ) target else null
                // Эмоциональные голоса: реплика звучит с эмоцией (страх выше
                // и быстрее, утешение ниже и медленнее). Тумблер выключен —
                // ровный голос, как раньше.
                val prosody = if (prefs.emotionalVoices().get()) {
                    guessEmotion(speakTextRaw).let { e ->
                        if (e == Emotion.NEUTRAL) null else e.pitch to e.rate
                    }
                } else {
                    null
                }
                when (speakAndAwait(spokenText, gender, slot, langHint, prosody)) {

                    SpeakOutcome.SPOKEN, SpeakOutcome.SILENT -> rejectedStreak = 0
                    SpeakOutcome.NO_ENGINE -> {
                        blockAutoread(NO_VOICE_MESSAGE)
                        return@launch
                    }
                    SpeakOutcome.REJECTED, SpeakOutcome.STALLED -> {
                        // Разовый отказ — обычное дело. Серия отказов означает,
                        // что озвучки нет: дальше листать нечего. Голос,
                        // замолчавший на середине фразы, — такой же отказ:
                        // раньше он молча удерживал страницу до таймаута.

                        rejectedStreak++
                        if (rejectedStreak >= REJECTED_STOP_AFTER) {
                            blockAutoread(REJECTED_VOICE_MESSAGE)
                            return@launch
                        }
                    }
                }
                // Плавный режим вебтуна: реплика дочитана — прокрутить ровно
                // на её высоту, чтобы следующая была уже внизу вьюпорта.
                if (onLineSpoken != null) {
                    runCatching { onLineSpoken(region.boundingBox) }
                        .onFailure { logcat(LogPriority.WARN, it) { "onLineSpoken failed" } }
                }
                spokenLines.add(lineKey(region.text))
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            logcat(LogPriority.ERROR, e) { "AutoRead frame failed" }
            OcrHistoryStore.addAutoRead(false, "сбой страницы", e.message ?: e.javaClass.simpleName)
            // Сбой кадра раньше просто дочитывался, а потом колбэк листал
            // дальше: читатель получал молча пролистанные страницы. Серия
            // сбоев останавливает авточтение с объяснением.
            noteOcrFailure(e.message ?: e.javaClass.simpleName)

        } finally {
            // Кадр освобождаем на ЛЮБОМ выходе, включая отмену: иначе
            // каждый прерванный кадр авточтения оставлял после себя
            // полноэкранный битмап.
            releaseFrame()
            aiRefine?.cancel()
            // Общее состояние кадра — только если его не перебил более новый
            // кадр, и по frameCounter, а не по generation: остановка по
            // существу (нет озвучки, OCR не отвечает) увеличивает generation,
            // и старая проверка `myGen == generation` пропускала очистку —
            // рамка с номером реплики замерзала на странице, а кнопка «Стоп»
            // оставалась в состоянии «идёт». На этом пути кадр всегда
            // ПОСЛЕДНИЙ, поэтому гасить ему можно и нужно.
            if (myFrame >= frameCounter) {
                _currentRegion.value = null
                _frameRegions.value = emptyList()
                streamedRegionCount.set(0)
                frameGeometry = null
                _isReading.value = false
                // Колбэк только для АКТУАЛЬНОГО запуска: после stop() старый
                // цикл не имеет права листать дальше или перезапускать чтение
                if (myGen == generation && job?.isCancelled != true) {

                    onPageFinished()
                }
            }
        }
    }
}

/**
 * Итог «Скриншот сейчас»: что реально удалось сделать с кадром.
 *
 * Существует ради одного требования — тост должен быть честным. Пока
 * сохранение было одной строкой без результата, кнопка сообщала
 * «Скриншот сохранён» даже тогда, когда JPEG выбрасывался, и читатель
 * искал файл, которого нет ни в буфере, ни в галерее.
 */
sealed interface ScreenshotResult {
    /** Кадр сохранён и во внутренний буфер, и в публичную папку Pictures/Yomikai. */
    data class SavedInGallery(val galleryUri: Uri) : ScreenshotResult

    /**
     * Кадр сохранён только во внутренний буфер «Скриншоты»: публичное
     * хранилище недоступно (нет прав на запись, MediaStore отказал).
     */
    data class SavedInAppOnly(val reason: String) : ScreenshotResult

    /** Кадр не сохранён нигде, [reason] объясняет почему. */
    data class NotSaved(val reason: String) : ScreenshotResult
}

/**
 * Мгновенный скриншот: распознать текущий кадр выбранным движком (в т.ч.
 * Glens) и сохранить его в буфер «Скриншоты» И в общую галерею
 * (`Pictures/Yomikai`), НЕ озвучивая и не трогая состояние авточтения.
 * Вызывается с плавающей кнопки читалки.
 *
 * Кадр читается ЗДЕСЬ, на потоке вызывающего, и в фон уходит его копия.
 * Раньше фоновой задаче отдавался исходный битмап, а вызывающий
 * переиспользовал его сразу же: гонка приводила к `getPixels` по
 * переиспользованному битмапу, и приложение падало сразу после сообщения
 * «Скриншот сохранён» — без всякой ошибки на экране.
 *
 * Функция suspend и возвращает [ScreenshotResult]: раньше она молча уходила
 * в `return@launch` на пяти ветках (выключенный преф, переиспользованный
 * битмап, не удалось скопировать кадр, таймаут OCR, пустой OCR), а читалка
 * всё равно показывала «Скриншот сохранён» — и читатель искал файл там,
 * где его нет. Теперь тост показывается по факту.
 */
suspend fun captureInstantScreenshot(
    bitmap: Bitmap,
    chapterId: Long,
    pageIndex: Int,
    scrollFraction: Float,
    geometry: OcrFrameGeometry? = null,
): ScreenshotResult {
    if (!prefs.autoScreenshotEnabled().get()) {
        return ScreenshotResult.NotSaved("автоскриншоты выключены в настройках")
    }
    if (bitmap.isRecycled) return ScreenshotResult.NotSaved("кадр уже освобождён")

    // Фоновой задаче нужна ЕЁ копия. Кадр вызывающего может быть
    // переиспользован сразу после возврата, а уменьшение не всегда
    // требуется — тогда downscaleForScan отдаёт тот же объект, и гонка
    // вернулась бы вместе с падением по переиспользованному битмапу.

package eu.kanade.tachiyomi.data.tts

/**
 * Самодельный ВСТРОЕННЫЙ AI-помощник озвучки. Никаких API-ключей и сети:
 * пол говорящего определяется лингвистической эвристикой прямо на устройстве.
 *
 * Для русского текста работает морфология:
 *  • глаголы прошедшего времени от первого лица: «сказала/подумала/пришла…»
 *    → женская реплика; «сказал/подумал/пришёл…» → мужская;
 *  • самоописания: «я рада», «я сама», «я готова» vs «я рад», «я сам»,
 *    «я готов»;
 *  • обращения-маркеры: «сестрёнка, ты…», «братик, ты…» относятся к
 *    собеседнику и НЕ учитываются для говорящего.
 *
 * Скоринг: считаем женские и мужские маркеры, отвечаем полом только при
 * явном перевесе — иначе null (нейтральный голос). Лучше промолчать, чем
 * озвучить неверным полом.
 */
object LocalSpeakerAi {

    // «я/мне/меня …-ла» — окончание прошедшего времени ж.р.
    private val feminineVerb = Regex("""(?:^|\s)(?:я|ведь я|и я)\s+(?:\S+\s+){0,2}?\S+ла(?:сь)?\b""")
    private val masculineVerb = Regex("""(?:^|\s)(?:я|ведь я|и я)\s+(?:\S+\s+){0,2}?\S+(?:[^аеиоуыэюяль]|ёл|ел|ал|ул|ил|ыл|л)(?:ся)?\b""")

    private val feminineSelf = listOf(
        "я сама", "я рада", "я готова", "я должна", "я уверена", "я согласна",
        "я не могла", "я была", "я хотела", "я думала", "я поняла", "я знала",
        "я видела", "я слышала", "я пришла", "я решила", "сама справлюсь",
        "я устала", "я испугалась", "я замужем",
        // самоидентификация через существительные
        "я мама", "я мать", "я сестра", "я дочь", "я бабушка", "я девушка",
        "я женщина", "я принцесса", "я королева", "я ведьма", "я учительница",
        // самоидентификация через прилагательные
        "я красивая", "я сильная", "я умная", "я добрая", "я злая",
        "я беременна", "я влюблена", "я свободна", "я занята", "я права",
    )
    private val masculineSelf = listOf(
        "я сам", "я рад", "я готов", "я должен", "я уверен", "я согласен",
        "я не мог", "я был", "я хотел", "я думал", "я понял", "я знал",
        "я видел", "я слышал", "я пришёл", "я пришел", "я решил", "сам справлюсь",
        "я устал", "я испугался", "я женат",
        // самоидентификация через существительные
        "я папа", "я отец", "я брат", "я сын", "я дед", "я мужчина", "я парень",
        "я юноша", "я принц", "я король", "я воин", "я рыцарь", "я маг",
        // самоидентификация через прилагательные
        "я красивый", "я сильный", "я умный", "я добрый", "я злой",
        "я свободен", "я занят", "я прав", "я виноват",
    )

    /** Пол говорящего: "female" | "male" | null (не уверены). */
    fun guessGender(rawText: String): String? {
        val text = " " + rawText.lowercase().replace('ё', 'ё') + " "

        var female = 0
        var male = 0

        for (marker in feminineSelf) if (text.contains(marker)) female += 2
        for (marker in masculineSelf) if (text.contains(marker)) male += 2

        if (feminineVerb.containsMatchIn(text)) female += 1
        else if (masculineVerb.containsMatchIn(text)) male += 1

        return when {
            female > male -> "female"
            male > female -> "male"
            else -> null
        }
    }

    /**
     * Пол для каждой реплики кадра. Реплики без явных маркеров наследуют
     * пол предыдущей уверенной реплики того же кадра только если стоят
     * вплотную (диалог одного персонажа из нескольких бабблов подряд).
     */
    fun guessGenders(lines: List<String>): List<String?> {
        val result = arrayOfNulls<String>(lines.size)
        for (i in lines.indices) {
            result[i] = guessGender(lines[i])
        }
        return result.toList()
    }

    /**
     * СЛОВАРНАЯ подстраховка (пол по упомянутым лицам). Голосует только при
     * ЧИСТОМ признаке: в реплике упомянут ровно один пол. Оба пола сразу —
     * это разговор О ком-то, пол говорящего не определяем (null → нарратор).
     * v1.9.135: ранее эта эвристика жила в AutoReadEngine и перевешивала
     * count'ами даже смешанные маркеры — отсюда инвертируемые голоса при
     * авточтении. Вынесена сюда, чтобы быть доступной unit-тестам без
     * android-зависимостей.
     */
    fun genderByMentions(text: String): String? {
        // Основы (не формы), чтобы ловить все падежи: «сестра/сестры/
        // сестрёнка/сестре», «принцесса/принцессой» и т.д. Конфликтные корни
        // не берём («корол-» совпадает с «королева» ж.р., «мам» — с «мамка»).
        val maleMarkers = listOf(
            "брат", "отц", "пап", "дед", "сын", "мужчин", "парн",
            "господин", "старик", "мальчик", "юнош", "принц", "король",
        )
        val femaleMarkers = listOf(
            "сестр", "мате", "мам", "бабушк", "доч", "женщин", "девушк",
            "госпож", "старух", "девочк", "принцесс", "королева",
        )
        val lower = text.lowercase()
        // Подстрочный поиск покрывает падежи: «моей сестры», «к отцу».
        val maleCount = maleMarkers.count { lower.contains(it) }
        val femaleCount = femaleMarkers.count { lower.contains(it) }
        if (maleCount > 0 && femaleCount > 0) return null
        return when {
            maleCount > 0 -> "male"
            femaleCount > 0 -> "female"
            else -> null
        }
    }

}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import android.speech.tts.TextToSpeech
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Продвинутый резолвер голосов: 1 / 2 / 3 голоса.
 *
 * Запрос пользователя:
 *  - 1 голос — один нарратор (выбор муж/жен) озвучивает всё
 *  - 2 голоса — мужской и женский (локальный или онлайн) по полу реплики
 *  - 3 голоса — муж + жен + нарратор (отдельный выбор)
 *
 *Каждый из трёх слотов имеет свой движок:
 *  - `pref_voice_male_engine`  → male
 *  - `pref_voice_female_engine`→ female
 *  - `pref_voice_narrator_engine` → narrator
 *и свой голос внутри движка (`pref_voice_male`, `pref_voice_female`, `pref_voice_name` для нарратора).
 *
 * Логика [resolve] применяется в [TtsSpeaker.speakAs] и [AutoReadEngine].
 */
object VoiceModeResolver {

    enum class Mode(val id: String, val title: String, val desc: String) {
        SINGLE("single", "Один голос", "Весь текст — голосом нарратора"),
        DUAL("dual", "Два голоса", "Мужские реплики — мужским, женские — женским"),
        TRIPLE("triple", "Три голоса", "Муж + Жен + Нарратор (описания, ремарки)"),
        /** Много голосов: свой голос каждому персонажу одного пола в сцене. */
        MULTI("multi", "Много голосов", "Отдельный голос каждому персонажу одного пола"),
        ;

        companion object {
            fun fromId(id: String?): Mode = entries.firstOrNull { it.id == id } ?: DUAL
        }
    }

    data class ResolvedVoice(
        val gender: String, // male | female | narrator
        val engine: String, // system_tts | google_web | remote_tts | eleven_api
        val voiceName: String,
        val isLocal: Boolean,
        val isOnline: Boolean,
    )

    private fun prefs(): OcrPreferences = Injekt.get()

    fun currentMode(): Mode = Mode.fromId(prefs().voiceMode().get())

    fun narratorGender(): String = prefs().narratorGender().get().lowercase().let {
        when (it) {
            "male", "female" -> it
            else -> "female" // auto → female по умолчанию
        }
    }

    /**
     * Выбрать голос для реплики с учётом режима и пола, определённого
     * морфологией/AI (female/male/null).
     *
     * @param detectedGender пол реплики от RuMorph/AI: "female"|"male"|null
     * @param isNarration был ли текст помечен как нарратив (без кавычек, описания)
     */
    fun resolve(
        detectedGender: String?,
        isNarration: Boolean = false,
        speakerSlot: Int = 0,
    ): ResolvedVoice {
        val mode = currentMode()
        val p = prefs()

        return when (mode) {
            Mode.SINGLE -> {
                val g = narratorGender()
                val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                val name = when (g) {
                    "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                    else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                }
ResolvedVoice(
                    gender = g,
                    engine = engine,
                    voiceName = name,
                    isLocal = engine == TtsSpeaker.ENGINE_SYSTEM || engine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = engine == TtsSpeaker.ENGINE_GOOGLE_WEB || engine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.DUAL -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.TRIPLE -> {
                if (isNarration) {
                    val g = narratorGender()
                    val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                    val name = when (g) {
                        "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                        else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                    }
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                } else {
                    val g = detectedGender ?: "female"
                    val isMale = g == "male"
                    val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                    val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                }
            }
            // Много голосов: по полу, как DUAL; отдельные слоты персонажам
            // назначаются в AutoReadEngine (speakerSlot), здесь voice тот же.
            Mode.MULTI -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
        }
    }

    fun describeCurrent(): String {
        val mode = currentMode()
        val p = prefs()
        return when (mode) {
            Mode.SINGLE -> "Один голос: нарратор ${narratorGender()} (${p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }})"
            Mode.DUAL -> "Два голоса: муж (${p.voiceMaleEngine().get().ifBlank { "system_tts" }}) + жен (${p.voiceFemaleEngine().get().ifBlank { "system_tts" }})"
            Mode.TRIPLE -> "Три голоса: муж (${p.voiceMaleEngine().get()}) + жен (${p.voiceFemaleEngine().get()}) + нарратор ${narratorGender()} (${p.voiceNarratorEngine().get()})"
            Mode.MULTI -> "Много голосов: отдельный голос каждому персонажу одного пола"
        }
    }

    /**
     * Применить resolved-голос к TextToSpeech: setVoice + rate/pitch от VoicePreset.
     */
    fun applyToTts(
        tts: TextToSpeech?,
        resolved: ResolvedVoice,
        rate: Float,
        pitch: Float,
    ) {
        if (tts == null) return
        val kind = when (resolved.gender) {
            "male" -> VoiceKind.MALE
            "female" -> VoiceKind.FEMALE
            else -> VoiceKind.OTHER
        }
        val voice = VoiceHelper.pickFor(tts, kind, resolved.voiceName.takeIf { it.isNotBlank() }, "ru", null)
        if (voice != null) {
            runCatching { tts.voice = voice }
        }
        tts.setSpeechRate(rate)
        tts.setPitch(pitch)
    }
}

package eu.kanade.tachiyomi.data.tts

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.Build
import androidx.core.app.NotificationCompat
import eu.kanade.tachiyomi.R
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Уведомление «Сейчас читается»: распознанный текст страницы + кнопка
 * «⏹ Остановить» прямо в шторке. Текст остаётся в уведомлении, даже когда
 * озвучка закончилась — можно перечитать.
 */
object TtsReadingNotifier {

    private const val CHANNEL_ID = "yomikai_tts_reading"
    private const val NOTIFICATION_ID = 0x77A1
    private const val ACTION_STOP = "app.yomikai.TTS_STOP"

    @Volatile
    private var receiverRegistered = false

    /**
     * Читатель нажал «⏹ Остановить» в шторке.
     *
     * Кнопка раньше только глушила синтез: цикл авточтения продолжал листать
     * главу, кадр за кадром проглатывался в тишину, и читатель получал
     * пролистанную главу вместо остановки. Теперь запрос доходит до цикла
     * через [consumeStopRequest].
     */
    @Volatile
    private var stopRequested = false

    /**
     * Забрать запрос «остановить», если он был. Одноразово.
     *
     * Запрос сбрасывается чтением, а не показом уведомления: показ случается
     * в начале каждого кадра и затер бы ответ, который читатель уже дал.
     */
    fun consumeStopRequest(): Boolean {
        if (!stopRequested) return false
        stopRequested = false
        return true
    }

    private val stopReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context, intent: Intent) {
            if (intent.action == ACTION_STOP) {
                stopRequested = true

                TtsSpeaker.stop()
                dismiss(context)
            }
        }
    }

    /**
     * Лимит текста в уведомлении.
     *
     * Android отбрасывает Notification, чей суммарный размер превышает
     * ~500 КБ (RemoteViews / Bundle), и падает с TransactionTooLargeException
     * либо DeadObjectException, залив logcat простынёй. Полная страница OCR
     * легко даёт несколько тысяч символов, поэтому режем жёстко.
     */
    private const val MAX_NOTIFICATION_TEXT = 800

    /**
     * Показать уведомление о чтении.
     *
     * [pageLabel] — где читатель находится в главе («Страница 3 из 20»).
     * Показывается под заголовком: авточтение читает главу, а не одну
     * страницу, и без такой подсказки шторка выглядит как зависшая на первой.
     */
    fun show(context: Context, text: String, pageLabel: String? = null) {

        if (text.isBlank()) return
        val app = context.applicationContext
        val nm = app.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            nm.createNotificationChannel(
                NotificationChannel(
                    CHANNEL_ID,
                    "Озвучка страниц",
                    NotificationManager.IMPORTANCE_LOW,
                ),
            )
        }

        if (!receiverRegistered) {
            val filter = IntentFilter(ACTION_STOP)
            try {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                    app.registerReceiver(stopReceiver, filter, Context.RECEIVER_NOT_EXPORTED)
                } else {
                    @Suppress("UnspecifiedRegisterReceiverFlag")
                    app.registerReceiver(stopReceiver, filter)
                }
                receiverRegistered = true
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "Failed to register TTS stop receiver" }
            }
        }

        val stopIntent = PendingIntent.getBroadcast(
            app,
            0,
            Intent(ACTION_STOP).setPackage(app.packageName),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE,
        )

        val safeText = text.take(MAX_NOTIFICATION_TEXT)
        val notification = NotificationCompat.Builder(app, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_mihon)
            .setContentTitle(pageLabel?.let { "🔊 Читается глава · $it" } ?: "🔊 Читается страница")

            .setContentText(safeText.take(120))
            .setStyle(NotificationCompat.BigTextStyle().bigText(safeText))
            .setOnlyAlertOnce(true)
            .setOngoing(false)
            .addAction(0, "⏹ Остановить", stopIntent)
            .build()

        // Без разрешения POST_NOTIFICATIONS (Android 13+) notify() бросает
        // SecurityException; уведомление — не повод ронять читалку.
        try {
            nm.notify(NOTIFICATION_ID, notification)
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "TTS notification rejected" }
        }
    }

    fun dismiss(context: Context) {
        val nm = context.applicationContext
            .getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.cancel(NOTIFICATION_ID)
    }

    /**
     * Снять уведомление и дать задерегистрировать приёмник «⏹ Остановить».
     *
     * Регистрация шла на applicationContext, поэтому без явного shutdown
     * приёмник висел навсегда: процесс держал ссылку на объект-сироту до
     * самого перезапуска приложения. Вызывается из `destroy()` владельцев
     * чтения (ReaderActivity, BrowserTab, OcrOverlayService).
     */
    fun shutdown(context: Context) {
        dismiss(context)
        if (!receiverRegistered) return
        receiverRegistered = false
        runCatching {
            context.applicationContext.unregisterReceiver(stopReceiver)
        }.onFailure { e ->
            logcat(LogPriority.WARN, e) { "Failed to unregister TTS stop receiver" }
        }
    }

}

package eu.kanade.tachiyomi.data.tts

/**
 * Разметка реплик для озвучки.
 *
 * На экране у каждой реплики есть служебные пометки — номер по порядку
 * чтения, кто говорит, пауза. Их должно быть ВИДНО, но TTS не должен их
 * произносить. Поэтому текст для показа и текст для синтеза расходятся:
 * [strip] снимает разметку перед отправкой в движок.
 *
 * Поддерживаемые пометки:
 *
 * | Запись        | Значение                                   | Читается |
 * |---------------|--------------------------------------------|----------|
 * | `{1}`         | номер реплики в порядке чтения             | нет      |
 * | `{ж}` `{м}`   | пол говорящего (женский / мужской)         | нет      |
 * | `{ж2}`        | вторая женщина в сцене (свой голос)        | нет      |
 * | `{имя:Аки}`   | имя говорящего                             | нет      |
 * | `{пауза}`     | дополнительная пауза перед репликой        | нет      |
 * | `{...}`       | любая другая служебная пометка             | нет      |
 * | `÷`           | разделитель частей реплики (короткая пауза)| нет      |
 *
 * Всё, что не в фигурных скобках, читается как обычно.
 *
 * Имя говорящего живёт в метке `{имя:Аки}`, но авточтение получает текст из
 * OCR, где меток нет. Поэтому есть и обратный путь: [speakerNameFromText]
 * распознаёт подпись персонажа в самой реплике («АКИ: …», «Аки — …»), а
 * [withSpeakerName] прикрепляет метку обратно. Метка снимается в [strip] и на
 * экране, и в синтезе, поэтому имя не начинает произноситься дважды.
 */
object SpeechMarkup {

    // ВАЖНО: фигурные скобки внутри класса символов обязаны быть экранированы.
    // На JVM/ART без экрана работает и без экрана, но ICU-движок регулярок
    // (Itel, Infinix и др. Android 13+) бросает PatternSyntaxException прямо в
    // <clinit>, из-за чего ЛЮБОЕ обращение к TTS роняло приложение
    // (ExceptionInInitializerError).
    private val TAG = Regex("""\{[^\{\}]{0,40}\}""")
    private val DIVIDER = '÷'

    /**
     * Подпись персонажа в начале реплики капсом: «АКИ: …», «АКИ — …»,
     * «КИМ ЧЕН: …». В комиксах и вебтунах имя набрано прописными, а сама
     * реплика — строчными, поэтому такой префикс надёжно отличает имя от
     * обычного слова, даже если OCR не сохранил шрифт.
     */
    private val CAPS_NAME = Regex(
        """^\s*([A-ZА-ЯЁ][A-ZА-ЯЁ'\-]{1,23}(?:\s+[A-ZА-ЯЁ][A-ZА-ЯЁ'\-]{1,23})?)\s*[:—–]\s*(\S.*)$""",
    )

    /**
     * Подпись персонажа с одной заглавной буквы: «Аки: …», «Аки — …».
     * Разрешаем не короче трёх букв: «Нет: я не знаю» и «Помоги — где ты?»
     * превратились бы в «нового персонажа» с собственным голосом.
     */
    private val TITLE_NAME = Regex(
        """^\s*([А-ЯЁA-Z][а-яёa-z]{2,23}(?:\s+[А-ЯЁA-Z][а-яёa-z]{2,23})?)\s*[:—–]\s*(\S.*)$""",
    )

    /**
     * Слова, с которых реплика не может начинаться как с имени. Список
     * короткий и явный: угадывать «имя» по одной заглавной букве нельзя, иначе
     * любая короткая реплика («Он ушёл», «Помоги — где ты?») завела бы себе
     * отдельный голос, а роль из словаря получала бы чужое имя.
     */
    private val NOT_A_NAME = setOf(
        "э", "эй", "ах", "хм", "ну", "о", "а", "и", "у", "не", "нет", "да",
        "ты", "вы", "он", "она", "мы", "все", "вот", "это", "так", "затем",
        "потом", "потому", "поэтому", "значит", "вдруг", "опять", "снова",
        "если", "когда", "чтобы", "ладно", "слушай", "смотри", "боже",
        "господи", "чёрт", "кто", "что", "где", "куда", "зачем", "привет",
        "здравствуй", "пока", "прости", "извини", "спасибо", "глава", "том",
        "помоги", "попробуй", "подожди", "пожалуйста", "иди", "стой", "беги",
        "неужели", "правда", "точно", "хорошо", "отлично", "увы", "помощь",
    )

    /** Допустимые символы имени: без фигурных скобок, иначе метка не распарсится. */
    private val NAME_NOISE = Regex("""[^\p{L}\p{N} ._'’\-]""")

    /** Пол, объявленный разметкой: "female" | "male" | null. */
    fun genderOf(text: String): String? {
        val m = TAG.findAll(text).map { it.value.trim('{', '}').lowercase() }
        m.forEach {
            when {
                it.startsWith("ж") || it.startsWith("f") -> return "female"
                it.startsWith("м") || it.startsWith("m") -> return "male"
            }
        }
        return null
    }

    /**
     * Номер говорящего в сцене: `{ж2}` -> 1 (второй женский слот),
     * `{ж}`/`{м}` -> 0. Нужен, чтобы два персонажа одного пола звучали
     * разными голосами.
     */
    fun speakerSlot(text: String): Int {
        TAG.findAll(text).forEach { match ->
            val body = match.value.trim('{', '}').lowercase()
            if (body.startsWith("ж") || body.startsWith("м") ||
                body.startsWith("f") || body.startsWith("m")
            ) {
                val digits = body.dropWhile { !it.isDigit() }.takeWhile { it.isDigit() }
                if (digits.isNotEmpty()) return (digits.toIntOrNull() ?: 1).minus(1).coerceAtLeast(0)
                return 0
            }
        }
        return 0
    }

    /** Есть ли запрос на дополнительную паузу перед репликой. */
    fun hasPause(text: String): Boolean =
        TAG.findAll(text).any { it.value.trim('{', '}').lowercase().startsWith("пауза") }

    /** Имя говорящего из `{имя:Аки}`, если задано. */
    fun speakerName(text: String): String? {
        TAG.findAll(text).forEach { match ->
            val body = match.value.trim('{', '}')
            val lower = body.lowercase()
            if (lower.startsWith("имя:") || lower.startsWith("name:")) {
                return body.substringAfter(':').trim().ifBlank { null }
            }
        }
        return null
    }

    /**
     * Имя говорящего из САМОГО текста реплики («АКИ: …», «Аки — …»).
     *
     * Зачем это нужно. Метку `{имя:…}` авточтение раньше не собирало, поэтому
     * словарь голосовых ролей не мог сработать на OCR-чтении вообще: оставался
     * «только пол», а настроенные роли молча игнорировались. Второе применение
     * — слот голоса персонажа (см. AutoReadEngine.voiceSlotFor): без имени
     * третью реплику того же героя не отличить от нового персонажа, и голос
     * менялся на каждой реплике.
     */
    fun speakerNameFromText(text: String): String? {
        val line = text.trim()
        if (line.isEmpty()) return null
        CAPS_NAME.find(line)?.let { match ->
            val name = cleanName(match.groupValues[1])
            // Подпись без реплики («АКИ —») — это заголовок панели, а не реплика.
            if (name != null && match.groupValues[2].isNotBlank()) return name
        }
        TITLE_NAME.find(line)?.let { match ->
            val name = cleanName(match.groupValues[1])
            if (name != null) return name
        }
        return null
    }

    /** Имя реплики: из разметки, иначе из текста. Порядок важен — разметка точнее. */
    fun speakerNameOrGuess(text: String): String? =
        speakerName(text) ?: speakerNameFromText(SpeechMarkup.strip(text))

    /**
     * Прикрепляет метку `{имя:…}` к реплике, если имени ещё нет. Само слово
     * имени при этом НЕ вырезается: читатель слышит подпись так же, как видит
     * её на кадре, а служебная метка снимается в [strip] и не произносится.
     */
    fun withSpeakerName(text: String, name: String?): String {
        if (speakerName(text) != null) return text
        val clean = cleanName(name) ?: return text
        return "{имя:$clean} $text"
    }

    /**
     * Имя приводится к безопасному виду: без фигурных скобок (иначе метка
     * распадётся и будет произнесена), без переносов и не длиннее 24 символов
     * (длина метки в [TAG] ограничена 40 символами вместе со скобками).
     */
    private fun cleanName(raw: String?): String? {
        val cleaned = raw.orEmpty()
            .replace('\n', ' ')
            .replace(NAME_NOISE, " ")
            .replace(Regex("""\s+"""), " ")
            .trim()
        if (cleaned.length < 2 || cleaned.lowercase() in NOT_A_NAME) return null
        return cleaned.take(24)
    }

    /**
     * Текст для синтеза: разметка убрана, `÷` заменён на запятую (короткая
     * пауза), лишние пробелы схлопнуты.
     */
    fun strip(text: String): String {
        var out = normalizeSpeechPunctuation(text)
        out = TAG.replace(out, " ")

        out = out.replace(DIVIDER, ',')
        out = out.replace(Regex("[~≈]+"), "") // тильду не озвучивать словом «тильда»
        out = out.replace(Regex("""\s+"""), " ")
        out = out.replace(Regex("""\s+([,.!?;:])"""), "$1")
        out = out.replace(Regex(""",{2,}"""), ",")
        return out.trim().trim(',').trim()
    }

    fun forSpeech(text: String): String {
        var out = text.replace(Regex("\\.{2,}"), "…")
        out = out.replace(Regex("!{2,}"), "!!")
        out = out.replace(Regex("\\?{2,}"), "??")
        out = out.replace(Regex("([!?]{2})[!?]+"), "$1")
        out = out.replace(Regex("(?:;;|:){2,}"), ";")
        out = out.replace(Regex("\\s+([,!?;:…])"), "$1")
        out = out.replace(Regex("(^|\\s)[.,!?;:·•*#|/^_=+<>]+(\\s|$)"), " ")
        out = out.replace(Regex(",{2,}"), ",")
        out = out.replace(Regex("\\s{2,}"), " ")
        return out.trim().trim(',').trim()
    }

    /**
     * Нормализация «японской» и полноширинной пунктуации перед синтезом.
     *
     * Google Lens и сканлатеры часто отдают реплики с полноширинными знаками
     * (＂！＂, ＂？＂, ＂：＂, ＂。＂, CJK-скобки), а синтезатор читает такие знаки
     * ВСЛУХ словами («восклицательный знак», «двоеточие», «правая скобка»)
     * вместо паузы и интонации. Приводим их к обычным ASCII/типографским
     * аналогам — движок даёт им эмоцию и паузу, как задумано. Сами буквы и
     * слова любых языков не трогаем: меняются только служебные знаки.
     */
    private fun normalizeSpeechPunctuation(text: String): String = buildString(text.length) {
        for (c in text) {
            when {
                // Полноширинные ASCII-формы U+FF01..FF5E (! ~ 0-9 A-Z a-z) — обычные.
                c in '！'..'～' -> append(c - 0xFEE0)
                else -> when (c) {
                    '　' -> append(' ') // идеографический пробел
                    '。' -> append('.')
                    '、' -> append(',')
                    // CJK-скобки: голос говорил «скобка». Рамку цитаты озвучивать
                    // нечем — просто снимаем её (остаётся сама реплика).
                    '「', '」', '『', '』', '【', '】', '〈', '〉', '《', '》', '〔', '〕' -> append(' ')
                    '・', '･' -> append(' ')
                    // Долгота каны и волнистые черты звука не имеют —
                    // проговариваться словами тоже не должны.
                    'ー', '〜', '∼' -> Unit
                    else -> append(c)
                }
            }
        }
    }


    /** Добавляет номер реплики в начало, если его там ещё нет. */
    fun withIndex(text: String, index: Int): String =
        if (TAG.containsMatchIn(text) && text.trimStart().startsWith("{$index}")) {
            text
        } else {
            "{$index} $text"
        }

    /** Собирает пометки для показа: `{3}{ж2}` перед текстом. */
    fun tagsOf(text: String): String =
        TAG.findAll(text).joinToString("") { it.value }
}

package mihon.data.ocr

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder
import org.json.JSONArray

/**
 * Service providing instant translation for manga OCR text.
 * Supports Google Translate, DeepL, and LLM translation gateways.
 */
object MangaTranslatorService {

    /** Переводчик может расставить пробелы внутри @@@ — учитываем это. */
    private val SEPARATOR_REGEX = Regex("""\s*@\s*@\s*@\s*""")

    /**
     * Переводит СПИСОК реплик одним запросом.
     *
     * Раньше авточтение переводило по одной реплике на HTTP-запрос: на
     * странице с 15 бабблами это 15 последовательных обращений между
     * озвучками. Здесь строки склеиваются разделителем, который переводчик
     * не трогает, и режутся обратно; при несовпадении числа строк —
     * безопасный откат на построчный перевод.
     */
    suspend fun translateAll(
        texts: List<String>,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): List<String> = withContext(Dispatchers.IO) {
        if (texts.isEmpty()) return@withContext emptyList()
        if (texts.size == 1) return@withContext listOf(translate(texts[0], targetLang, sourceLang))

        // Разделитель из символов, которые переводчик оставляет как есть.
        val separator = "\n@@@\n"
        val joined = texts.joinToString(separator)

        // У endpoint есть лимит на длину query — режем на порции.
        if (joined.length > 1500) {
            val half = texts.size / 2
            return@withContext translateAll(texts.take(half), targetLang, sourceLang) +
                translateAll(texts.drop(half), targetLang, sourceLang)
        }

        val translated = translate(joined, targetLang, sourceLang)
        val parts = translated.split(SEPARATOR_REGEX).map { it.trim() }
        if (parts.size == texts.size) {
            parts.mapIndexed { index, part -> part.ifBlank { texts[index] } }
        } else {
            logcat(LogPriority.INFO) { "Batch translate mismatch, falling back to per-line" }
            texts.map { translate(it, targetLang, sourceLang) }
        }
    }

    /**
     * Translates input text into target language (default: Russian "ru").
     */
    suspend fun translate(
        text: String,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): String = withContext(Dispatchers.IO) {
        if (text.isBlank()) return@withContext ""

        try {
            // Instant Google Free Translate API
            val encodedText = URLEncoder.encode(text, "UTF-8")
            val urlString = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=$sourceLang&tl=$targetLang&dt=t&q=$encodedText"

            val connection = (URL(urlString).openConnection() as HttpURLConnection).apply {
                requestMethod = "GET"
                connectTimeout = 8_000
                readTimeout = 15_000
                setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
            }

            val responseText = connection.inputStream.use { it.readBytes().toString(Charsets.UTF_8) }
            val jsonArray = JSONArray(responseText)
            val sentences = jsonArray.optJSONArray(0)

            val translatedBuilder = StringBuilder()
            if (sentences != null) {
                for (i in 0 until sentences.length()) {
                    val sentence = sentences.optJSONArray(i)
                    if (sentence != null) {
                        translatedBuilder.append(sentence.optString(0, ""))
                    }
                }
            }

            connection.disconnect()
            val result = translatedBuilder.toString().trim()
            if (result.isNotBlank()) result else text
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Manga translation failed for: $text" }
            text
        }
    }
}

