private val wordRegex = Regex("[A-Za-zА-Яа-яЁё0-9'ʼ’]+")

private fun tokensOf(s: String): List<WordTok> =
    wordRegex.findAll(s).map { m -> WordTok(m.range.first, m.range.last + 1, m.value.lowercase()) }.toList()

